import re
seq = []
with open('region.fasta') as f:
    for line in f:
        if not line.startswith('>'): seq.append(line.strip())
S = ''.join(seq).upper()
L = len(S)

# microsatellites via backreference-free pattern
print("homopolymer runs >=6:")
for m in re.finditer(r'(A{6,}|C{6,}|G{6,}|T{6,})', S):
    print("  ", m.group(1)[0]*(len(m.group(1))), "at", m.start()+1, "-", m.end())

print("\ndi-nucleotide repeats (>=6 copies):")
for m in re.finditer(r'(.{2})\1{5,}', S):
    print("  unit", m.group(1), "at", m.start()+1, "-", m.end(), ":", m.group(0))

print("\ntri-nucleotide repeats (>=4 copies):")
for m in re.finditer(r'(.{3})\1{3,}', S):
    print("  unit", m.group(1), "at", m.start()+1, "-", m.end(), ":", m.group(0))

# long exact repeated words
print("\nlongest exactly repeated words:")
for k in range(25, 14, -1):
    words = {}
    hits = []
    for i in range(L-k+1):
        w = S[i:i+k]
        words.setdefault(w, []).append(i)
    for w, pos in words.items():
        if len(set(pos)) >= 2:
            hits.append((w, [p+1 for p in pos]))
    if hits:
        print(f"  k={k}: {hits[:5]}")
        break

# tandem/direct duplicated blocks (longer, inexact) - quick check with windows
print("\nrepeated 100bp blocks (>=80% identity):")
def sim(a,b):
    return sum(1 for x,y in zip(a,b) if x==y)/len(a)
blocks = []
for i in range(0, L-100, 25):
    for j in range(i+100, L-100, 25):
        s1, s2 = S[i:i+100], S[j:j+100]
        sc = sim(s1,s2)
        if sc > 0.80:
            blocks.append((sc, i+1, j+1))
blocks.sort(reverse=True)
for sc,a,b in blocks[:8]:
    print(f"   {a}-{a+99} vs {b}-{b+99}  identity {sc:.2f}")

